// Cloudflare Workers entry: the OpenNext worker for every request, plus the
// daily ritual scan that vercel.json's cron used to run. The Cron Trigger is
// declared in wrangler.jsonc; the route checks Authorization: Bearer CRON_SECRET.
// `.open-next/worker.js` is generated by `npm run cf:build`.
import handler from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  async scheduled(_event, env, ctx) {
    const origin = (env.APP_ORIGIN || "https://aangan.invalid").replace(/\/$/, "");
    const req = new Request(`${origin}/api/ritual-scan`, { headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } });
    const res = await handler.fetch(req, env, ctx);
    console.log(`[cron] ritual-scan ${res.status}`);
  },
};
